import xml.etree.ElementTree as ET, os, glob
for f in sorted(glob.glob('*.drawio')):
    try:
        t=ET.parse(f); r=t.getroot()
        cells=r.findall('.//mxCell')
        v=[c for c in cells if c.get('vertex')=='1']
        e=[c for c in cells if c.get('edge')=='1']
        ids={c.get('id') for c in cells}
        bad=[]
        for c in e:
            for k in ('source','target'):
                if c.get(k) and c.get(k) not in ids: bad.append((c.get('id'),k,c.get(k)))
        # orphan parents
        badp=[c.get('id') for c in cells if c.get('parent') and c.get('parent') not in ids]
        print(f'{f}')
        print(f'   XML OK | vertices={len(v)} edges={len(e)}')
        print(f'   dangling edge refs: {bad if bad else \"none\"}')
        print(f'   bad parent refs:    {badp if badp else \"none\"}')
        print(f'   size: {os.path.getsize(f)//1024} KB')
    except Exception as ex:
        print(f'{f}  ***PARSE FAILED*** {ex}')
"
